/** 一覧で読んだときから更新されていなければ書く。書けたかを返す */
async saveIfUnchanged(order: Order, readAt: Date): Promise<boolean> {
  const result = this.#db
    .prepare(
      `UPDATE orders SET status = ?, charge_id = ?, updated_at = ?
       WHERE id = ? AND updated_at = ?`,
    )
    .run(order.status, order.chargeId ?? null, this.#now().toISOString(),
      order.id, readAt.toISOString());
  return result.changes === 1;
}
